(* [comment removed for export] *)
Definition cell_eqb (c d : Z * Z * Z) : bool := Z.eqb (fst (fst c)) (fst (fst d)) && Z.eqb (snd (fst c)) (snd (fst d)) && Z.eqb (snd c) (snd d).
Lemma cell_in_b : forall c l, existsb (cell_eqb c) l = true -> In c l.
